FILES={'engine/geo_source_cards/source_scope.py': {'source': 'geo-source-card-collectors/geo_source_cards/source_scope.py', 'before': 'e089ac755de1e3d9fd2d4f157e7d9a9d51b047ec2e258086f43842308a3ad793', 'text': '"""Conservative, task-derived topic checks before paying for article research."""\nimport re\nfrom collections import Counter\n\n# These are generic containers and conversational words, not product identities.\nGENERIC = (\'精华液\',\'精华乳\',\'精华水\',\'精粹水\',\'护肤品\',\'化妆品\',\'产品\',\'成分\',\'配方\',\'护理\',\'日常\',\'男士\',\'女士\',\'选购\',\'选择\',\'推荐\',\'哪些\',\'怎么\',\'什么\',\'可以\',\'值得\',\'应该\',\'注意\',\'信息\',\'使用\',\'适合\',\'自己\',\'比较\',\'首次\',\'第一次\',\'购买\',\'挑选\',\'挑选\',\'保持\',\'清洁\')\nTOPIC_ALIASES = (frozenset((\'造型喷雾\',\'定型喷雾\',\'塑型喷雾\',\'塑形喷雾\',\'发型喷雾\',\'蓬松喷雾\')),)\n\ndef anchors(questions, product):\n    name = str(product.get(\'name\',\'\')).replace(str(product.get(\'brand\',\'\')),\'\')\n    name = \'\'.join(re.findall(r\'[\\u4e00-\\u9fff]+\',name))\n    counts = Counter()\n    for question in questions:\n        parts = re.findall(r\'[\\u4e00-\\u9fff]+\',question)\n        terms = {p[i:i+n] for p in parts for n in range(2,8) for i in range(len(p)-n+1)}\n        counts.update(terms)\n    threshold = max(1,(len(questions)+1)//2)\n    terms = [s for s,n in counts.items() if n>=threshold and s in name and not any(s in g for g in GENERIC)]\n    maximal=[s for s in terms if not any(s!=other and s in other for other in terms)]\n    result=set(maximal)\n    for term in maximal:\n        core=term\n        for generic in GENERIC:core=core.replace(generic,\'\')\n        if len(core)>=2:result.add(core)\n    return sorted(result,key=lambda s:(-len(s),s))\n\ndef evaluate(source, terms):\n    article=source.get(\'article\',{});title=article.get(\'title\') or source.get(\'title\',\'\');body=article.get(\'text\',\'\')\n    if not terms:return {\'status\':\'unscoped\',\'anchors\':[],\'matched\':[]}\n    matched=[];aliases={}\n    for term in terms:\n        variants=next((group for group in TOPIC_ALIASES if term in group),{term})\n        found=[s for s in sorted(variants) if s in title or (s in body[:1000] and sum(s in p for p in body.splitlines() if p.strip())>=2)]\n        if found:\n            matched.append(term)\n            if term not in found:aliases[term]=found\n    return {\'status\':\'ready\' if matched else \'off_topic\',\'anchors\':terms,\'matched\':matched,**({\'matched_aliases\':aliases} if aliases else {})}\n'}}
TESTS={'test_jsonl_records.py': 'import json\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom . import materials\nfrom geo_source_cards.source_analysis import load_records\n\n\nclass JsonlRecordsTests(unittest.TestCase):\n    def test_unicode_separators_preserved_and_duplicates_deduplicated(self):\n        with tempfile.TemporaryDirectory() as directory:\n            root=Path(directory)\n            path=root/\'days/2026-10-31/baidu_ai/results.jsonl\'\n            path.parent.mkdir(parents=True)\n            row={\'question\':\'题目\',\'model\':\'baidu_ai\',\'task_id\':\'a\',\'captured_at\':1,\n                 \'text\':\'原文\\u0085下一段\\u2028仍在原文\\u2029末段\',\'body_capture_complete\':True}\n            text=json.dumps(row,ensure_ascii=False)\n            path.write_text(text+\'\\n\'+text+\'\\n\',encoding=\'utf8\')\n            self.assertEqual(materials.records(\'2026-10-31\',\'题目\',[\'baidu_ai\'],root),[row])\n            self.assertEqual(materials.read_lines(path),[row,row])\n            self.assertEqual(load_records(path),[row,row])\n\n    def test_real_corruption_is_not_silently_ignored(self):\n        with tempfile.TemporaryDirectory() as directory:\n            path=Path(directory)/\'broken.jsonl\'\n            path.write_text(\'{"question":"truncated\\n\',encoding=\'utf8\')\n            for reader in (materials.read_lines,load_records):\n                with self.assertRaises(json.JSONDecodeError):reader(path)\n', 'test_response_framing.py': 'import json,unittest\nfrom .client import recover_transport_json\n\nclass ResponseFramingTests(unittest.TestCase):\n    def test_exact_dsml_tail_preserves_draft(self):\n        result={\'draft_markdown\':\'# 标题\\n正文“引号”\\n尾段\'}\n        suffix=\'</｜｜DSML｜｜ parameter>\\n</｜｜DSML｜｜ invoke>\\n</｜｜DSML｜｜ calls>\'\n        self.assertEqual(recover_transport_json(json.dumps(result,ensure_ascii=False)+suffix)[0],result)\n\n    def test_extra_prose_or_second_object_not_accepted(self):\n        for tail in [\' instructions\',\'{}\',\'</script>\',\'\']:\n            with self.assertRaises(ValueError):recover_transport_json(\'{"draft_markdown":"text"}\'+tail)\n\n    def test_stray_quote_only_with_complete_skeleton(self):\n        result={\'article_type\':\'ranking\',\'tone\':\'客观\',\'article_structure\':[\'开头\',\'比较\'],\n                \'writing_rhythm\':\'先慢后快\',\'special_style_elements\':[],\'forbidden_pattern\':[]}\n        value=json.dumps(result,ensure_ascii=False).replace(\'], "writing_rhythm"\',\']", "writing_rhythm"\')\n        self.assertEqual(recover_transport_json(value)[0],result)\n        with self.assertRaises(ValueError):recover_transport_json(\'{"article_structure":["x"]", "writing_rhythm":"y"}\')\n', 'test_source_cache.py': "import hashlib\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom geo_source_cards.runtime import atomic_json\nfrom .source_cache import SourceCache, failure_kind\n\n\nclass SourceCacheTests(unittest.TestCase):\n    def test_reuses_previous_round_without_extending_age(self):\n        with tempfile.TemporaryDirectory() as directory:\n            root = Path(directory); url = 'https://example.com/a'\n            key = hashlib.sha256(url.encode()).hexdigest() + '.json'\n            old = root / 'private_source_analysis-supplement-2/article_cache' / key\n            atomic_json(old, dict(status='fetched', requested_url=url, fetched_at=100, text='body'))\n            calls = []\n            fetch = lambda u: calls.append(u) or dict(status='fetched', text='new')\n            cache = SourceCache(root, fetch, clock=lambda: 200)\n            self.assertEqual(cache(url)['text'], 'body')\n            self.assertEqual(calls, [])\n            # Downstream analysis stamps a new fetched_at; actual read age wins.\n            result = {**cache(url), 'fetched_at': 86500}\n            atomic_json(old, result)\n            cache.clock = lambda: 86501\n            self.assertEqual(cache(url)['text'], 'new')\n            self.assertEqual(calls, [url])\n\n    def test_dns_failure_retries_after_short_cooldown(self):\n        with tempfile.TemporaryDirectory() as directory:\n            calls = []; now = [100]\n            def fetch(url):\n                calls.append(url)\n                return dict(status='failed', attempts=[dict(error='Temporary failure in name resolution')]) if len(calls)==1 else dict(status='fetched', text='recovered')\n            cache = SourceCache(directory, fetch, clock=lambda: now[0])\n            self.assertEqual(cache('https://example.com/a')['failure_kind'], 'dns')\n            now[0] = 159\n            self.assertEqual(cache('https://example.com/a')['status'], 'failed')\n            self.assertEqual(len(calls), 1)\n            now[0] = 160\n            self.assertEqual(cache('https://example.com/a')['text'], 'recovered')\n\n    def test_corrupt_and_wrong_url_cache_do_not_supply_content(self):\n        with tempfile.TemporaryDirectory() as directory:\n            url = 'https://example.com/a'; root = Path(directory)\n            p = root/'source_read_cache'/(hashlib.sha256(url.encode()).hexdigest()+'.json')\n            p.parent.mkdir();p.write_text('{')\n            calls = []\n            cache = SourceCache(root, lambda u: calls.append(u) or dict(status='fetched', text=u), clock=lambda:100)\n            self.assertEqual(cache(url)['text'], url)\n            atomic_json(p, dict(status='fetched', requested_url='https://example.com/b', fetched_at=100))\n            self.assertEqual(cache(url)['text'], url)\n            self.assertEqual(len(calls), 2)\n\n    def test_failure_reasons(self):\n        self.assertEqual(failure_kind(dict(attempts=[dict(error='HTTP 404')])), 'not_found')\n        self.assertEqual(failure_kind(dict(error='Verification/access-denied page is not an article')), 'verification')\n\n\nif __name__ == '__main__':\n    unittest.main()\n", 'test_shared_source_cache.py': "import hashlib,json,sqlite3,tempfile,unittest\nfrom datetime import datetime\nfrom pathlib import Path\nfrom zoneinfo import ZoneInfo\nfrom .source_cache import SourceCache\n\nclass SharedSourceCacheTests(unittest.TestCase):\n def setUp(self):\n  self.tmp=tempfile.TemporaryDirectory();self.root=Path(self.tmp.name);self.db=self.root/'content.sqlite'\n  self.url='https://baijiahao.baidu.com/s?id=123';self.body='真实的完整文章内容。'*60\n  with sqlite3.connect(self.db) as db:\n   db.execute('create table source_content(url text primary key,final_url text,status text,fetched_at text,extraction_quality text,content_text text,text_length integer,content_hash text,title text,extraction_method text)')\n   db.execute('insert into source_content values(?,?,?,?,?,?,?,?,?,?)',(self.url,self.url,'ok','2026-10-31 08:00:00','high',self.body,len(self.body),hashlib.sha256(self.body.encode()).hexdigest(),'原文标题','article_node'))\n  self.at=datetime(2026,10,31,8,tzinfo=ZoneInfo('Asia/Shanghai')).timestamp();self.calls=[]\n  self.cache=SourceCache(self.root/'job',lambda url:self.calls.append(url) or {'status':'failed'},clock=lambda:self.at+3600,content_db=self.db)\n def tearDown(self):self.tmp.cleanup()\n def test_reuse_exact_snapshot_preserves_age_and_database(self):\n  before=self.db.read_bytes();value=self.cache(self.url)\n  self.assertEqual(value['status'],'fetched');self.assertEqual(value['source_read_at'],self.at)\n  self.assertEqual(value['reused_from'],'geo_source_content_sqlite');self.assertEqual(self.calls,[])\n  self.assertEqual(self.db.read_bytes(),before)\n def test_expired_snapshot_is_not_reused(self):\n  self.cache.clock=lambda:self.at+86400\n  self.assertIsNone(self.cache.shared_article(self.url))\n def test_quality_and_hash_are_required(self):\n  for field,value,original in [('extraction_quality','low','high'),('content_hash','wrong',hashlib.sha256(self.body.encode()).hexdigest()),('status','blocked','ok')]:\n   with self.subTest(field=field):\n    with sqlite3.connect(self.db) as db:db.execute('update source_content set '+field+'=?',(value,))\n    self.assertIsNone(self.cache.shared_article(self.url))\n    with sqlite3.connect(self.db) as db:db.execute('update source_content set '+field+'=?',(original,))\n def test_verification_redirect_and_other_url_rejected(self):\n  self.assertIsNone(self.cache.shared_article(self.url+'4'))\n  with sqlite3.connect(self.db) as db:db.execute('update source_content set final_url=?',('https://wappass.baidu.com/static/captcha/tuxing.html',))\n  self.assertIsNone(self.cache.shared_article(self.url))\n", 'test_topic_aliases.py': "import unittest\nfrom geo_source_cards.source_scope import evaluate\n\nclass TopicAliasesTests(unittest.TestCase):\n def test_styling_synonyms_match(self):\n  for word in ['定型喷雾','塑型喷雾','发型喷雾','蓬松喷雾']:\n   value=evaluate({'article':{'title':'敏感头皮如何选择温和'+word,'text':''}},['造型喷雾'])\n   self.assertEqual(value['status'],'ready')\n   self.assertIn(word,value['matched_aliases']['造型喷雾'])\n def test_cosmetic_sprays_and_unrelated_topics_remain_excluded(self):\n  for title in ['定妆喷雾购买指南','保湿喷雾推荐','香水喷雾测评','防晒喷雾哪个好']:\n   self.assertEqual(evaluate({'article':{'title':title,'text':''}},['造型喷雾'])['status'],'off_topic')\n def test_footer_single_mention_not_enough(self):\n  self.assertEqual(evaluate({'article':{'title':'护肤知识','text':'保湿方法。\\n相关推荐：定型喷雾。'}},['造型喷雾'])['status'],'off_topic')\n"}
